INSERT INTO public.ch_zi1 (id, zi, translation, pinyin, description, example) VALUES
                                                                                 (1, '我', 'я, меня', 'wǒ', 'Я — это рука с оружием/копьем (戈), защищающая свое «Я».', '我是学生。 Wǒ shì xuésheng. — Я студент.'),
                                                                                 (2, '我们', 'мы, нас', 'wǒmen', 'Множественное число от «я»', '我们去机场。 Wǒmen qù jīchǎng. — Мы едем в аэропорт.'),
                                                                                 (3, '你', 'ты', 'nǐ', 'Ты — человек (亻) с ультимативным правом указывать на собеседника.', '你好！ Nǐ hǎo! — Привет!'),
                                                                                 (4, '他', 'он, его', 'tā', 'Он — человек (亻) мужского пола, раньше обозначался через образ другого человека.', '他是我的朋友。 Tā shì wǒ de péngyou. — Он мой друг.'),
                                                                                 (5, '她', 'она', 'tā', 'Она — женщина (女) в профиль, сидящая скромно и покорно.', '她是老师。 Tā shì lǎoshī. — Она преподаватель.'),
                                                                                 (6, '这', 'это, этот', 'zhè', 'Это/этот — знак пересечения дорог и выбора конкретного объекта под ногами.', '这是什么？ Zhè shì shénme? — Что это?'),
                                                                                 (7, '那', 'то, тот', 'nà', 'Тот — указание на то, что находится на удалении, вовне.', '那是一本书。 Nà shì yī běn shū. — То — книга.'),
                                                                                 (8, '哪', 'какой, который', 'nǎ', 'Какой — образ птицы/фазана, которая высматривает добычу, задавая вопрос.', '你是哪国人？ Nǐ nǎ guórén? — Ты какой национальности?'),
                                                                                 (9, '哪儿', 'где, куда', 'nǎr', 'Вопросительное слово места', '你在哪儿？ Nǐ zài nǎr? — Ты где?'),
                                                                                 (10, '谁', 'кто', 'shéi', 'Кто — словно два человека шепчутся, выясняя личность друг друга.', '他是谁？ Tā shì shéi? — Кто он?'),
                                                                                 (11, '什么', 'что, какой', 'shénme', 'Что — рот (口) задает вопрос о человеке или предмете.', '你想吃什么？ Nǐ xiǎng chī shénme? — Что ты хочешь съесть?'),
                                                                                 (12, '多少', 'сколько', 'duōshǎo', 'Сколько — несколько малых элементов, соединенных вместе в кучу.', '多少钱？ Duōshǎo qián? — Сколько это стоит?'),
                                                                                 (13, '几', 'сколько, несколько', 'jǐ', 'Используется для счета обычно до 10', '你几岁？ Nǐ jǐ suì? — Сколько тебе лет?'),
                                                                                 (14, '怎么', 'как, каким образом', 'zěnme', 'Как — образ ребенка (子), который учится делать все впервые.', '这个怎么读？ Zhège zěnme dú? — Как это читается?'),
                                                                                 (15, '怎么样', 'как, каков', 'zěnmeyàng', 'Каков — вопрос, требующий развернутого описания качеств.', '今天天气怎么样？ Jīntiān tiānqì zěnmeyàng? — Какая сегодня погода?'),
                                                                                 (16, '一', 'один', 'yī', 'Один — горизонтальная черта, начало счета, линия горизонта.', '一个苹果 Yī gè píngguǒ — Одно яблоко'),
                                                                                 (17, '二', 'два', 'èr', 'Два — две параллельные линии (вторая длиннее).', '二月 Èr yuè — Февраль'),
                                                                                 (18, '三', 'три', 'sān', 'Три — три горизонтальные линии, символизирующие троицу мира.', '三个人 Sān gè rén — Три человека'),
                                                                                 (19, '四', 'четыре', 'sì', 'Четыре — похоже на окно с перегородками или раскрытые пальцы рук.', '四本书 Sì běn shū — Четыре книги'),
                                                                                 (20, '五', 'пять', 'wǔ', 'Пять — перекрестие дорог или пальцев на руке.', '五分钟 Wǔ fēnzhōng — Пять минут'),
                                                                                 (21, '六', 'шесть', 'liù', 'Шесть — пиктограмма крыши и опор, символизирующая прочность числа.', '六月 Liù yuè — Июнь'),
                                                                                 (22, '七', 'семь', 'qī', 'Семь — пересечение линий, похожее на цифру 7 или разрез.', '七点 Qī diǎn — Семь часов'),
                                                                                 (23, '八', 'восемь', 'bā', 'Восемь — две линии расходятся в стороны, как крылья или разделение.', '八楼 Bā lóu — Восьмой этаж'),
                                                                                 (24, '九', 'девять', 'jiǔ', 'Девять — изогнутый крючок, почти завершивший полный круг.', '九月 Jiǔ yuè — Сентябрь'),
                                                                                 (25, '十', 'десять', 'shí', 'Десять — крест (+), полнота, все стороны света сошлись в одной точке.', '十个人 Shí gè rén — Десять человек'),
                                                                                 (26, '个', 'универсальное счетное слово', 'gè', 'Самое частое счетное слово для предметов и людей', '一个汉字 Yī gè hànzì — Один иероглиф'),
                                                                                 (27, '岁', 'год (возраст)', 'suì', 'Счетное слово для возраста', '我二十岁。 Wǒ èrshí suì. — Мне 20 лет.'),
                                                                                 (28, '本', 'счетное слово для книг', 'běn', 'Используется для книг, журналов, тетрадей', '一本书 Yī běn shū — Одна книга'),
                                                                                 (29, '些', 'немного, несколько', 'xiē', 'Указывает на неопределенное количество', '这些 Zhè xiē — Эти'),
                                                                                 (30, '块', 'кусок, юань (разг.)', 'kuài', 'Кусок/юань — металлическая монета (元 — первоначальный).', '十块钱 Shí kuài qián — 10 юаней'),
                                                                                 (31, '不', 'не', 'bù', 'Не — птица летит вниз, перечеркивая траекторию; категорический отказ.', '我不知道。 Wǒ bù zhīdào. — Я не знаю.'),
                                                                                 (32, '没', 'нет (отрицание для глагола 有)', 'méi', 'Нет (не было) — водная стихия (氵) и рука, которая ничего не нашла в пустом сосуде.', '我没有钱。 Wǒ méiyǒu qián. — У меня нет денег.'),
                                                                                 (33, '很', 'очень', 'hěn', 'Очень — шаг в сторону (彳) и скрещенные знаки; когда чего-то чересчур.', '天气很好。 Tiānqì hěn hǎo. — Погода очень хорошая.'),
                                                                                 (34, '太', 'слишком, чересчур', 'tài', 'Слишком — цифра «большой» (大) с избыточной капелькой снизу (перебор).', '太贵了！ Tài guì le! — Слишком дорого!'),
                                                                                 (35, '都', 'все, всё', 'dōu', 'Все — солнце светит на всех одинаково, охватывая каждого.', '我们都是学生。 Wǒmen dōu shì xuésheng. — Мы все студенты.'),
                                                                                 (36, '一点儿', 'немного, чуть-чуть', 'yīdiǎnr', 'Немного — «один» (一) + «капля» (点) времени или размера; совсем чуть-чуть.', '我想吃一点儿。 Wǒ xiǎng chī yīdiǎnr. — Я хочу поесть немного.'),
                                                                                 (37, '和', 'и, с', 'hé', 'И, с — злаки (禾) разделены поровну во рту (口); делим по-братски вместе с кем-то.', '我和他。 Wǒ hé tā. — Я и он.'),
                                                                                 (38, '在', 'в, на, находиться', 'zài', 'В, на, находиться — трава/росток прорастает из земли в определенном месте.', '他在家。 Tā zài jiā. — Он дома.'),
                                                                                 (39, '的', 'притяжательная частица', 'de', 'Притяжательная частица — ложка (勺) черпает из белого (白) сосуда то, что принадлежит кому-то.', '我的书。 Wǒ de shū. — Моя книга.'),
                                                                                 (40, '了', 'глагольная/модальная частица', 'le', 'Частица свершения — согнутый побег или хвост завершенного действия.', '我吃了。 Wǒ chī le. — Я поель (уже).'),
                                                                                 (41, '吗', 'вопросительная частица', 'ma', 'Вопросительная частица — рот (口) открыт в удивлении на краешке фразы (马 — просто звук).', '你是中国人吗？ Nǐ shì Zhōngguó rén ma? — Ты китаец?'),
                                                                                 (42, '呢', 'модальная частица', 'ne', 'Вопросительная частица (а ты?) — река (川) течет дальше, мягко переспрашивая.', '你呢？ Nǐ ne? — А ты? / А у тебя?'),
                                                                                 (43, '喂', 'алло, эй', 'wèi', 'Алло — рот (口) под защитой крыши; крик в трубку телефона.', '喂，你好！ Wèi, nǐ hǎo! — Алло, здравствуйте!'),
                                                                                 (44, '家', 'дом, семья', 'jiā', 'Дом, семья — свинья (豕) под крышей (宀); в древности богатство измерялось скотом в доме.', '我回家。 Wǒ huí jiā. — Я иду домой.'),
                                                                                 (45, '学校', 'школа, учебное заведение', 'xuéxiào', 'Школа — дерево (木) + знания (学); место, где растет ученик.', '我去学校。 Wǒ qù xuéxiào. — Я иду в школу.'),
                                                                                 (46, '饭店', 'ресторан, гостиница', 'fàndiàn', 'Ресторан — еда/рис (饭) + магазин/заведение (店); заведение, где вкусно кормят.', '他们在饭店吃饭。 Tāmen zài fàndiàn chīfàn. — Они кушают в ресторане.'),
                                                                                 (47, '商店', 'магазин', 'shāngdiàn', 'Магазин — крыша дома и лавка торговца (商), где продают товары.', '商店里有很多东西。 Shāngdiàn li yǒu hěnduō dōngxi. — В магазине много вещей.'),
                                                                                 (48, '医院', 'больница', 'yīyuàn', 'Больница — лечить (医) + просторный двор (院); место исцеления.', '他去了医院。 Tā qù le yīyuàn. — Он пошел в больницу.'),
                                                                                 (49, '中国', 'Китай', 'Zhōngguó', 'Китай — ровно посередине (中) обнесенного стеной государства (国).', '我喜欢中国。 Wǒ xǐhuān Zhōngguó. — Мне нравится Китай.'),
                                                                                 (50, '北京', 'Пекин', 'Běijīng', 'Пекин — северная (北) столица/высокое здание (京).', '北京是中国的首都。 Běijīng shì Zhōngguó de shǒudū. — Пекин — столица Китая.'),
                                                                                 (51, '上', 'верх, на, подниматься', 'shàng', 'Верх, на — указательный палец или черта указывает строго вверх над уровнем.', '书在桌子上。 Shū zài zhuōzi shàng. — Книга на столе.'),
                                                                                 (52, '下', 'низ, под, спускаться', 'xià', 'Низ, под — черта указывает под уровень земли или горизонта.', '下雨了。 Xià yǔ le. — Пошел дождь.'),
                                                                                 (53, '前面', 'перед, впереди', 'qiánmiàn', 'Впереди — рога животного и луна впереди; то, что прямо перед глазами.', '我在你前面。 Wǒ zài nǐ qiánmiàn. — Я впереди тебя.'),
                                                                                 (54, '后面', 'за, сзади', 'hòumiàn', 'Сзади — идти следом за кем-то, кто впереди (отпечаток ноги).', '他们在后面。 Tāmen zài hòumiàn. — Они позади.'),
                                                                                 (55, '里面', 'внутри, в', 'lǐmiàn', 'Внутри — поле/земля (田) глубоко внутри ограды или земли (里).', ' 盒子里面有什么? Hézi lǐmiàn yǒu shénme? — Что внутри коробки?'),
                                                                                 (56, '今天', 'сегодня', 'jīntiān', 'Сегодня — этот самый (今) день (天), который идет прямо сейчас.', '今天天气很好。 Jīntiān tiānqì hěn hǎo. — Сегодня погода очень хорошая.'),
                                                                                 (57, '明天', 'завтра', 'míngtiān', 'Завтра — солнце (日) и луна (月) сменяют друг друга наступая — новый день.', '明天见！ Míngtiān jiàn! — До завтра!'),
                                                                                 (58, '昨天', 'вчера', 'zuótiān', 'Вчера — прошедший день (昨), который уже ушел во вчерашний вечер.', '昨天是星期日。 Zuótiān shì xīngqī rì. — Вчера было воскресенье.'),
                                                                                 (59, '上午', 'утро (до полудня)', 'shàngwǔ', 'Утро — солнце поднимается над горизонтом (чертой).', '上午我有课。 Shàngwǔ wǒ yǒu kè. — У меня утром занятия.'),
                                                                                 (60, '中午', 'полдень, середина дня', 'zhōngwǔ', 'Полдень — ровно посередине (中) дня (午); стрелки часов замерли вертикально.', '中午吃什么？ Zhōngwǔ chī shénme? — Что едим в обед?'),
                                                                                 (61, '下午', 'после полудня, вторая половина дня', 'xiàwǔ', 'Вечер — солнце заходит за горизонт, сумерки сгущаются.', '下午好！ Xiàwǔ hǎo! — Добрый день!'),
                                                                                 (62, '年', 'год', 'nián', 'Год — созревание злаков (年), полный годовой цикл урожая.', '今年是2026年。 Jīnnián shì èr líng èr liù nián. — В этом году 2026 год.'),
                                                                                 (63, '月', 'месяц, луна', 'yuè', 'Месяц — изящный серп луны (月), отсчитывающий лунные месяцы.', '十月很冷。 Shíyuè hěn lěng. — Октябрь очень холодный.'),
                                                                                 (64, '号', 'номер, число (дата)', 'hào', 'День, дата — отрывной листочек календаря или солнечный день (日).', '今天几号？ Jīntiān jǐ hào? — Какое сегодня число?'),
                                                                                 (65, '星期', 'неделя', 'xīngqī', 'Звезды (星) и периоды/циклы (期)', '今天是星期一。 Jīntiān shì xīngqī yī. — Сегодня понедельник.'),
                                                                                 (66, '点', 'час (время), капля, точка', 'diǎn', 'Огонь снизу (灬) и следы — зажигать огонь, отмерять время', '现在三点。 Xiànzài sān diǎn. — Сейчас три часа.'),
                                                                                 (67, '分钟', 'минута', 'fēnzhōng', 'Минута — трава (艹) и разделение; маленькая доля часа, как травинка.', '等我五分钟。 Děng wǒ wǔ fēnzhōng. — Подожди меня пять минут.'),
                                                                                 (68, '现在', 'сейчас, теперь', 'xiànzài', 'Сейчас — капля воды или текущий момент прямо перед глазами.', '我现在很忙。 Wǒ xiànzài hěn máng. — Я сейчас очень занят.'),
                                                                                 (69, '时候', 'время, момент', 'shíhou', 'Время — солнце (日) и ступени/периоды (期).', '你什么时候去？ Nǐ shénme shíhou qù? — Когда ты идешь?'),
                                                                                 (70, '爸爸', 'папа', 'bàba', 'Папа — отец (父) держит в руке топор или семейный авторитет.', '爸爸不在家。 Bàba bù zài jiā. — Папы нет дома.'),
                                                                                 (71, '妈妈', 'мама', 'māma', 'Мама — женщина (女) и лошадь/мать (马) — главная кормилица очага.', '妈妈喜欢喝茶。 Māma xǐhuān hē chá. — Мама любит пить чай.'),
                                                                                 (72, '儿子', 'сын', 'érzi', 'Сын, ребенок — пиктограмма малыша с раскинутыми ручками (子).', '这是我的儿子。 Zhè shì wǒ de érzi. — Это мой сын.'),
                                                                                 (73, '女儿', 'дочь', 'nǚér', 'Дочь — женщина (女) + ребенок (子); любимая девочка в семье.', '他的女儿五岁。 Tā de nǚér wǔ suì. — Его дочери пять лет.'),
                                                                                 (74, '老师', 'учитель, преподаватель', 'lǎoshī', 'Учитель — старый, мудрый наставник (老), передающий опыт (师).', '老师好！ Lǎoshī hǎo! — Здравствуйте, учитель!'),
                                                                                 (75, '学生', 'студент, ученик', 'xuésheng', 'Ученик, студент — ребёнок (子) учится и познает мир (学).', '我是大学生。 Wǒ shì dàxué xuésheng. — Я студент университета.'),
                                                                                 (76, '同学', 'одноклассник, сокурсник', 'tóngxué', 'Одинаковый/совместный (同) + учиться (学)', '我们是好同学。 Wǒmen shì hǎo tóngxué. — Мы хорошие сокурсники.'),
                                                                                 (77, '朋友', 'друг', 'péngyou', 'Друг — два товарища рука об руку, идущие вместе (友).', '他-are мой лучший друг. 他是我的好朋友。 Tā shì wǒ de hǎo péngyou. — Он мой хороший друг.'),
                                                                                 (78, '医生', 'врач, доктор', 'yīshēng', 'Доктор, врач — врач держит инструменты исцеления (医).', '他是医生。 Tā shì yīshēng. — Он врач.'),
                                                                                 (79, '先生', 'господин, муж', 'xiānsheng', 'Раньше родившийся (先) — старший, уважаемый человек', '王先生在吗？ Wáng xiānsheng zài ma? — Господин Ван на месте?'),
                                                                                 (80, '小姐', 'мисс, девушка', 'xiǎojiě', 'Младшая (小) + барышня/сестра (姐)', '小姐，喝茶吗？ Xiǎojiě, hē chá ma? — Девушка, будете чай?'),
                                                                                 (81, '衣服', 'одежда', 'yīfu', 'Прикрытие для тела', '这件衣服很漂亮。 Zhè jiàn yīfu hěn piàoliang. — Эта одежда очень красивая.'),
                                                                                 (82, '水', 'вода', 'shuǐ', 'Вода — извилистые струйки чистой воды (水).', '我想喝水。 Wǒ xiǎng hē shuǐ. — Я хочу пить воду.'),
                                                                                 (83, '菜', 'блюдо, еда, овощи', 'cài', 'Трава/растения (艹) + знак расчленения — съедобные растения и еда', '中国菜很好吃。 Zhōngguó cài hěn hǎochī. — Китайская еда очень вкусная.'),
                                                                                 (84, '米饭', 'вареный рис', 'mǐfàn', 'Рис, еда — зерна риса, рассыпанные по тарелке.', '我 N/A -> 我吃米饭。 Wǒ chī mǐfàn. — Я ем рис.'),
                                                                                 (85, '水果', 'фрукты', 'shuǐguǒ', 'Вода/сочный (水) + плоды (果)', '我喜欢吃水果。 Wǒ xǐhuān chī shuǐguǒ. — Я люблю есть фрукты.'),
                                                                                 (86, '苹果', 'яблоко', 'píngguǒ', 'Яблоко — трава/дерево и птица/фрукт — сладкое сочное яблоко.', '这是一个大苹果。 Zhè shì yī gè dà píngguǒ. — Это большое яблоко.'),
                                                                                 (87, '茶', 'чай', 'chá', 'Чай — трава/растение (艹) + человек под крышей, пьющий целебный настой.', '请喝茶。 Qǐng hē chá. — Выпейте чаю.'),
                                                                                 (88, '杯子', 'чашка, стакан', 'bēizi', 'Чашка, стакан — дерево (木) + сосуд для напитков.', '杯子里有水。 Bēizi li yǒu shuǐ. — В чашке есть вода.'),
                                                                                 (89, '钱', 'деньги', 'qián', 'Металл/монеты (钅) + копье/оружие', '多少钱？ Duōshǎo qián? — Сколько это стоит?'),
                                                                                 (90, '飞机', 'самолет', 'fēijī', 'Летать (飞) + машина/аппарат (机)', '我们坐飞机去。 Wǒmen zuò fēijī qù. — Мы летим на самолете.'),
                                                                                 (91, '出租车', 'такси', 'chūzūchē', 'Такси — выходить/арендовать (出) + сдавать в аренду/брать (租) + машина (车); арендованная машина.', '我们坐出租车去。 Wǒmen zuò chūzūchē qù. — Мы поедем на такси.'),
                                                                                 (92, '电视', 'телевизор', 'diànshì', 'Телевизор — электричество (电) + зрение/видео (视); «электрическое окно» для просмотра передач.', '他在看电视。 Tā zài kàn diànshì. — Он смотрит телевизор.'),
                                                                                 (93, '电脑', 'компьютер', 'diànnǎo', 'Компьютер — электричество (电) + мозг (脑); электронный мыслительный мозг.', '我的电脑坏了。 Wǒ de diànnǎo huài le. — Мой компьютер сломался.'),
                                                                                 (94, '电影', 'моисей/кино', 'фильм', 'Фильм — электричество (电) + тень (影); движущиеся тени на экране под воздействием света.', '我想看电影。 Wǒ xiǎng kàn diànyǐng. — Я хочу посмотреть фильм.'),
                                                                                 (95, '天气', 'погода', 'tiānqì', 'Погода — небо (天) + дыхание/пар/воздух (气); воздушное состояние атмосферы неба.', '今天天气很好。 Jīntiān tiānqì hěn hǎo. — Сегодня отличная погода.'),
                                                                                 (96, '猫', 'кошка', 'māo', 'Кошка — звукоподражание «мяу» (кот) + ключевой знак животного (犭).', '我有一只猫。 Wǒ yǒu yī zhī māo. — У меня есть кошка.'),
                                                                                 (97, '狗', 'собака', 'gǒu', 'Собака — животное с изогнутым хвостом и лаем (собачий ключ 犭).', '那是一只大狗。 Nà shì yī zhī dà gǒu. — Это большая собака.'),
                                                                                 (98, '东西', 'вещь, предмет', 'dōngxi', 'Вещь, предмет — восток (东) и запад (西); всё, что куплено и принесено с восточных и западных базаров.', '买了很多东西。 Mǎi le hěnduō dōngxi. — Купил много вещей.'),
                                                                                 (99, '人', 'человек', 'rén', 'Человек — схематичное изображение идущего человека в профиль (две ноги).', '他是好人。 Tā shì hǎo rén. — Он хороший человек.'),
                                                                                 (100, '名字', 'имя', 'míngzi', 'Имя — вечер (夕) + рот (口); когда наступает темнота и не видно лиц, окликают друг друга по имени.', '你叫什么名字？ Nǐ jiào shénme míngzi? — Как тебя зовут?'),
                                                                                 (101, '书', 'книга', 'shū', 'Книга — изображение развернутой книги или стопки исписанных страниц на корешке.', '这是一本书。 Zhè shì yī běn shū. — Это книга.'),
                                                                                 (102, '汉语', 'китайский язык', 'hànyǔ', 'Китайский язык — народ Хань (汉) + речь/язык (语); язык великой династии.', '我学习汉语。 Wǒ xuéxí hànyǔ. — Я учу китайский язык.'),
                                                                                 (103, '字', 'иероглиф, слово, буква', 'zì', 'Иероглиф, буква — ребенок (子) под крышей дома (宀); рождение и воспитание новых знаков.', '这个字怎么读？ Zhè gè zì zěnme dú. — Как читается этот иероглиф?'),
                                                                                 (104, '桌子', 'стол', 'zhuōzi', 'Стол — деревянная конструкция (桌) + суффикс предмета (子).', '书在桌子上。 Shū zài zhuōzi shàng. — Книга на столе.'),
                                                                                 (105, '椅子', 'стул', 'yǐzi', 'Стул — дерево (木) + опора для сидения (椅) + суффикс (子).', '请 and sit -> 请坐 椅子。 Qǐng zuò yǐzi. — Пожалуйста, садитесь на стул.'),
                                                                                 (106, '谢谢', 'спасибо', 'xièxie', 'Спасибо — вежливое слово, состоящее из повторения корня благодарности (благодарить за жест).', '谢谢你！ Xièxie nǐ! — Спасибо тебе!'),
                                                                                 (107, '不客气', 'не за что, пожалуйста', 'búkèqì', 'Не за что — нет (不) + церемониться/стесняться (客气); «не церемоньтесь».', '— 谢谢！ — 不客气。 — Xièxie! — Búkèqì. — Спасибо! — Не за что.'),
                                                                                 (108, '再见', 'до свидания', 'zàijiàn', 'До свидания — снова/снова (再) + видеть/встречаться (见); «увидимся снова».', '明天见，再见！ Míngtiān jiàn, zàijiàn! — До завтра, до свидания!'),
                                                                                 (109, '请', 'просить, пожалуйста', 'qǐng', 'Пожалуйста, просить — речь (讠) + приглашение с чистым сердцем (青).', '请进。 Qǐng jìn. — Пожалуйста, входите.'),
                                                                                 (110, '对不起', 'извините, виноват', 'duìbuqǐ', 'Извините — лицом к лицу (对) + не (不) + поднимать глаза/смотреть в глаза (起); виноват, не могу смотреть прямо.', '对不起，我迟到了。 Duìbuqǐ, wǒ chídào le. — Извините, я опоздал.'),
                                                                                 (111, '没关系', 'ничего страшного, не имеет значения', 'méiguānxì', 'Ничего страшного — нет (没) + связь/отношение (关系); «это не имеет связи/последствий».', '— 对不起！ — 没关系。 — Duìbuqǐ! — Méiguānxì. — Извините! — Ничего страшного.'),
                                                                                 (112, '是', 'быть, являться, да', 'shì', 'Быть, являться, да — солнце над основанием; непоколебимая истина, точное «это так».', '我是学生。 Wǒ shì xuésheng. — Я студент.'),
                                                                                 (113, '有', 'иметь, обладать, иметься', 'yǒu', 'Иметь, обладать — рука (月/手) крепко держит кусок мяса или добычу.', '我有一辆车。 Wǒ yǒu yī liàng chē. — У меня есть машина.'),
                                                                                 (114, '看', 'смотреть, читать, навещать', 'kàn', 'Смотреть — рука (手) приставлена козырьком ко лбу, чтобы защитить глаза от солнца и вдаль вглядываться.', '她在看书。 Tā zài kàn shū. — Она читает книгу.'),
                                                                                 (115, '听', 'слушать', 'tīng', 'Слушать — рот/звук (口) воспринимает информацию ушами (знак сосредоточенного слуха).', '听我 说话。 Tīng wǒ shuōhuà. — Слушай, что я говорю.'),
                                                                                 (116, '说', 'говорить', 'shuō', 'Говорить — речь (讠) + обмен мыслями/радость (兑); изливать слова наружу.', '他说 汉语。 Tā shuō hànyǔ. — Он говорит по-китайски.'),
                                                                                 (117, '读', 'читать вслух, учиться', 'dú', 'Читать — речь (讠) + продавать/произносить вслух (卖); озвучивать написанный текст.', '学生在读课文。 Xuésheng zài dú kèwén. — Ученики читают текст вслух.'),
                                                                                 (118, '写', 'писать', 'xiě', 'Писать — образ кисти или руки, фиксирующей линии и знаки на бумаге.', '他在写字。 Tā zài xiězì. — Он пишет иероглифы.'),
                                                                                 (119, '看见', 'видеть, увидать', 'kànjiàn', 'Видеть, увидать — смотреть (看) + результат восприятия/достижения (见); разглядеть и зафиксировать.', '我看见他了。 Wǒ kànjiàn tā le. — Я его увидел.'),
                                                                                 (120, '叫', 'звать, по имени, кричать', 'jiào', 'Звать, по имени — открытый рот (口), из которого вылетает звук или имя человека.', '我叫 2026 -> 我叫, My name is... (например: 我叫马克 Wǒ jiào Mǎkè — Меня зовут Марк).'),
                                                                                 (121, '来', 'приходить, приезжать', 'lái', 'Приходить — пиктограмма пшеничного колоса, который "приходит" к людям как долгожданный урожай.', '欢迎光临，请进！ — 他什么时候来？ Tā shénme shíhou lái? — Когда он придет?'),
                                                                                 (122, '回', 'возвращаться, возвращаться назад', 'huí', 'Возвращаться — круговорот или вихрь (улитка), возвращающийся точно в исходную точку.', '我要回中国。 Wǒ yào huí Zhōngguó. — Я хочу вернуться в Китай.'),
                                                                                 (123, '去', 'идти, уходить, направляться', 'qù', 'Идти, уходить — человек уверенно шагает прочь от определенной точки.', '你去哪儿？ Nǐ qù nǎr? — Куда ты идешь?'),
                                                                                 (124, '吃', 'есть, кушать', 'chī', 'Есть, кушать — открытый рот (口) поглощает вкусную пищу.', '我想吃 苹果。 Wǒ xiǎng chī píngguǒ. — Я хочу съесть яблоко.'),
                                                                                 (125, '喝', 'пить', 'hē', 'Пить — рот (口) жадно припал к источнику живительной влаги.', '我想喝茶。 Wǒ xiǎng hē chá. — Я хочу выпить чаю.'),
                                                                                 (126, '睡觉', 'спать', 'shuìjiào', 'Спать — закрывать глаза/дремать (睡) + погружаться в сон (觉).', '太晚了，我要睡觉。 Tài wǎn le, wǒ yào shuìjiào. — Слишком поздно, я хочу спать.'),
                                                                                 (127, '打电话', 'звонить по телефону', 'dǎdiànhuà', 'Звонить по телефону — бить/делать (打) + электричество (电) + речь (话); битва проводов с голосом.', '他在打电话。 Tā zài dǎ diànhuà. — Он разговаривает по телефону.'),
                                                                                 (128, '做', 'делать, изготавливать', 'zuò', 'Делать — созидательный процесс творения, ручной работы или действия.', '你在做什么？ Nǐ zài zuò shénme? — Что ты делаешь?'),
                                                                                 (129, '买', 'покупать', 'mǎi', 'Покупать — сеть или ловушка (нетто), которой ловят и загребают нужные товары.', '我去商店买东西。 Wǒ qù shāngdiàn mǎi dōngxi. — Я иду в магазин за покупками.'),
                                                                                 (130, '开', 'открывать, водить (машину), включать', 'kāi', 'Открывать, водить — руки раздвигают засовы дверей или запускают механизм.', '请开门。 Qǐng kāi mén. — Пожалуйста, откройте дверь.'),
                                                                                 (131, '坐', 'сидеть, садиться, ехать (на транспорте)', 'zuò', 'Сидеть — два человека (人) сидят рядышком прямо на земле (土).', '请 坐。 Qǐng zuò. — Пожалуйста, садитесь.'),
                                                                                 (132, '住', 'жить, проживать', 'zhù', 'Жить, проживать — человек (亻) + хозяин дома (主); обосноваться где-то капитально.', '他住在北京。 Tā zhù zài Běijīng. — Он живет в Пекине.'),
                                                                                 (133, '学习', 'учиться, изучать', 'xuéxí', 'Учиться — подражать знаниям (学) + непрерывно практиковать их (习) как птенец крыльями.', '我学习汉语。 Wǒ xuéxí hànyǔ. — Я учу китайский язык.'),
                                                                                 (134, '工作', 'работать, работа', 'gōngzuò', 'Работать — орудие труда/мастерство (工) + созидание (作).', '我喜欢我的工作。 Wǒ xǐhuān wǒ de gōngzuò. — Мне нравится моя работа.'),
                                                                                 (135, '下雨', 'идти (о дожде)', 'xiàyǔ', 'Идет дождь — падение вниз (下) капель из грозовых туч (雨).', '外面下雨了。 Wàimiàn xiàyǔ le. — На улице пошел дождь.'),
                                                                                 (136, '爱', 'любить', 'ài', 'Любить — сердце (心) в центре эмоциональной привязанности и трепета.', '我爱你。 Wǒ ài nǐ. — Я люблю тебя.'),
                                                                                 (137, '喜欢', 'любить, нравиться', 'xǐhuān', 'Нравиться — ликование (喜) + душевный подъем и праздник (欢).', '我喜欢 Cтравники -> 我喜欢中国菜。 Wǒ xǐhuān Zhōngguó cài. — Мне нравится китайская еда.'),
                                                                                 (138, '想', 'хотеть, думать, скучать', 'xiǎng', 'Хотеть, скучать — мысль и глаз устремлены к сердцу (心) — то, чего сильно хочется.', '我想去中国。 Wǒ xiǎng qù Zhōngguó. — Я хочу поехать в Китай.'),
                                                                                 (139, '认识', 'знать, быть знакомым', 'rènshi', 'Знать, быть знакомым — распознавать лицо (认) + ведать человека (识).', '很高兴认识你。 Hěn gāoxìng rènshi nǐ. — Рад с вами познакомиться.'),
                                                                                 (140, '会', 'мочь, уметь (в результате обучения)', 'huì', 'Уметь — сложить детали воедино, овладеть полезным навыком после обучения.', '我会说汉语。 Wǒ huì shuō hànyǔ. — Я умею говорить по-китайски.'),
                                                                                 (141, '能', 'мочь, быть в состоянии (физически/по условиям)', 'néng', 'Мочь (физически) — мощный медведь, обладающий силой и ресурсами для дела.', '你 能 help me? -> 你能帮我吗？ Wǒ néng... — Можешь ли ты мне помочь?'),
                                                                                 (142, '好', 'хороший, добрый', 'hǎo', 'Хороший — женщина (女) с ребенком (子) рядом — абсолютная идиллия и благополучие.', '今天天气很好。 Jīntiān tiānqì hěn hǎo. — Сегодня отличная погода.'),
                                                                                 (143, '大', 'большой', 'dà', 'Большой — фигура человека, раскинувшего руки наотмашь, чтобы казаться крупнее.', '这是一个大苹果。 Zhè shì yī gè dà píngguǒ. — Это большое яблоко.'),
                                                                                 (144, '小', 'маленький', 'xiǎo', 'Маленький — дробление единого целого на крошечные частицы.', '这只猫很小。 Zhè zhī māo hěn xiǎo. — Эта кошка очень маленькая.'),
                                                                                 (145, '多', 'много', 'duō', 'Много — нагромождение слоев или кусков друг на друга (изобилие).', '这里人很多。 Zhèlǐ rén hěn duō. — Здесь очень много людей.'),
                                                                                 (146, '少', 'мало, немного', 'shǎo', 'Мало — скудный остаток после сильного деления.', '杯子里的水很少。 Bēizi lǐ de shuǐ hěn shǎo. — Воды в чашке очень мало.'),
                                                                                 (147, '冷', 'холодный', 'lěng', 'Холодный — ледяные кристаллы (冫) пробирают до костей.', '今天很冷。 Jīntiān hěn lěng. — Сегодня холодно.'),
                                                                                 (148, '热', 'горячий, жаркий', 'rè', 'Горячий — бушующий огонь (灬) шпарит снизу, излучая жар.', '夏天很热。 Xiàtiān hěn rè. — Летом очень жарко.'),
                                                                                 (149, '高兴', 'радостный, довольный', 'gāoxìng', 'Радостный — высокий полет (高) духа и подъем настроения (兴).', '我今天很高兴。 Wǒ jīntiān hěn gāoxìng. — Я сегодня очень рад.'),
                                                                                 (150, '漂亮', 'красивый, прекрасный', 'piàoliang', 'Красивый — яркий внешний вид, сияющий образ и лоск.', '她 穿 的 衣服 很 漂亮。 Tā chuān de yīfu hěn piàoliang. — Одежда, которую она носит, очень красива.'),
                                                                                 (151, '您', 'вы (уважительное)', 'nín', 'Вы — вежливая версия слова «ты» (你) с сердцем (心) снизу: обращение с уважением к человеку.', '您好！ Nín hǎo! — Здравствуйте!'),
                                                                                 (152, '它', 'оно', 'tā', 'Оно — местоимение для неодушевленных предметов и животных (раньше обозначало крышу или зверя).', '这是一只猫，它很可爱。 Zhè shì yī zhī māo, tā hěn kě''ài. — Это кошка, она очень милая.'),
                                                                                 (153, '大家', 'все, все вместе', 'dàjiā', 'Большой (大) + дом/семья (家); круг людей, собравшихся под одной крышей.', '大家好！ Dàjiā hǎo! — Всем привет!'),
                                                                                 (154, '每', 'каждый, всякий', 'měi', 'Мать с черточками-волоссями или повторяющиеся элементы: каждый на счету.', '每个学生都来了。 Měi gè xuésheng dōu lái le. — Каждый ученик пришел.'),
                                                                                 (155, '为什么', 'почему, отчего', 'wèishénme', 'Ради/для (为) + что (什么); вопрос о причине происходящего.', '你为什么去？ Nǐ wèishénme qù? — Почему ты идешь?'),
                                                                                 (156, '零', 'ноль', 'líng', 'Дождь (雨) и капли, падающие по чуть-чуть — пустое место, капля-ноль.', '今天零下五度。 Jīntiān língxià wǔ dù. — Сегодня пять градусов ниже нуля.'),
                                                                                 (157, '两', 'два, обе', 'liǎng', 'Два человека или предмета под навесом; используется перед счетными словами.', '我有两本书。 Wǒ yǒu liǎng běn shū. — У меня есть две книги.'),
                                                                                 (158, '百', 'сто', 'bǎi', 'Цифра один (一) под крышей/чертой счета — полная сотня завершенного счета.', '这是一百块。 Zhè shì yībǎi kuài. — Это сто юаней.'),
                                                                                 (159, '千', 'тысяча', 'tǐan', 'Десять (十) с нарисованным штрихом-«палочкой» сверху — возросшая в сто раз десятка.', '一千个字。 Yīqiān gè zì. — Тысяча иероглифов.'),
                                                                                 (160, '第一', 'первый', 'dìyī', 'Префикс порядка (第) + один (一); лидер гонки.', '他是第一名。 Tā shì dì yī míng. — Он занял первое место.'),
                                                                                 (161, '次', 'раз (счетное слово)', 'cì', 'Человек у воды или шаги, повторяющиеся определенное количество раз.', '我去过三次。 Wǒ qù guò sān cì. — Я был там три раза.'),
                                                                                 (162, '件', 'штука, предмет (для одежды, дел)', 'jiàn', 'Человек (亻) + делить/резать (牛) — отдельный предмет гардероба или дела.', '这是一件 衣服。 Zhè shì yī jiàn yīfu. — Это предмет одежды.'),
                                                                                 (163, '别', 'не надо, не делай; другой', 'bié', 'Нож (刂) разделяет кости и мясо — запрет или отделение.', '别说话！ Bié shuōhuà! — Не разговаривайте!'),
                                                                                 (164, '非常', 'очень, чрезвычайно', 'fēicháng', 'Не (非) + обычный (常); выходящий за рамки обычного, экстраординарный.', '今天非常热。 Jīntiān fēicháng rè. — Сегодня очень жарко.'),
                                                                                 (165, '也', 'тоже, также', 'yě', 'Пиктограмма змеи или вспомогательный элемент параллельного действия.', '我也是学生。 Wǒ yě shì xuésheng. — Я тоже студент.'),
                                                                                 (166, '还', 'еще, все еще', 'hái', 'Движение назад или возвращение к прежнему состоянию.', '我还有 Sth -> 我还有 钱。 Wǒ hái yǒu qián. — У меня все еще есть деньги.'),
                                                                                 (167, '最', 'самый (превосходная степень)', 'zuì', 'Голова сверху и солнце снизу — то, что возвышается над всем остальным.', '他是我最好的朋友。 Tā shì wǒ zuì hǎo de péngyou. — Он мой лучший друг.'),
                                                                                 (168, '真', 'настоящий, действительно', 'zhēn', 'Инструмент мастера и столб — подлинность, истина, прочность.', '天气真好。 Tiānqì zhēn hǎo. — Погода действительно хорошая.'),
                                                                                 (169, '正在', 'в процессе (совершения действия)', 'zhèngzài', 'Прямо (正) + находиться (在); действие происходит в данную секунду.', '他在 正在... -> 他在看书。 Tā zhèngzài kàn shū. — Он как раз читает книгу.'),
                                                                                 (170, '已经', 'уже', 'yǐjīng', 'Пройти (已) + пройти/минуть (经); точка невозвращения пройдена.', '他已经去了。 Tā yǐjīng qù le. — Он уже ушел.'),
                                                                                 (171, '一起', 'вместе', 'yìqǐ', 'Один (一) + подняться (起); объединение усилий в одной точке.', '我们一起去。 Wǒmen yìqǐ qù. — Мы идем вместе.'),
                                                                                 (172, '再', 'снова, опять', 'zài', 'Повторное движение или действие, которое совершится еще раз.', '再见！ Zàijiàn! — До свидания! (Увидимся снова).'),
                                                                                 (173, '就', 'то, именно, сразу же', 'jiù', 'Человек в ловушке или быстрое наступление действия/следствия.', '我就来。 Wǒ jiù lái. — Я сразу же приду.'),
                                                                                 (174, '因为……所以……', 'потому что… поэтому…', 'yīnwèi… suǒyǐ…', 'Причина (因为) и следствие (所以) — связка логической цепи.', '因为下雨，所以我不去。 Yīnwèi xiàyǔ, suǒyǐ wǒ bú qù. — Из-за того, что идет дождь, я не иду.'),
                                                                                 (202, '弟弟', 'младший брат', 'dìdi', 'Согнутый побег молодого растения, идущий следом за старшими.', '弟弟喜欢 苹果。 Dìdi xǐhuān píngguǒ. — Младший брат любит яблоки.'),
                                                                                 (175, '虽然……但是……', 'хотя… но…', 'suīrán… dànshì…', 'Уступка (虽然) и противопоставление (但是) в сложном предложении.', '虽然很累，但是很高兴. Suīrán hěn lèi, dànshì hěn gāoxìng. — Хотя устал, но очень рад.'),
                                                                                 (176, '从', 'из, от, с', 'cóng', 'Два человека идут друг за другом — движение откуда-то или следование.', '我从中国来。 Wǒ cóng Zhōngguó lái. — Я из Китая.'),
                                                                                 (177, '比', 'сравнивать, по сравнению с', 'bǐ', 'Два человека стоят бок о бок, соревнуясь в росте.', '他比我高。 Tā bǐ wǒ gāo. — Он выше меня.'),
                                                                                 (178, '往', 'направляться к, в сторону', 'wǎng', 'Шаг в сторону (彳) + стремление вперед/к цели (往).', '往前走。 Wǎng qián zǒu. — Идите вперед.'),
                                                                                 (179, '离', 'отстоять от, на расстоянии', 'lí', 'Птица, запутавшаяся в сетях или разделение/дистанция между объектами.', '我家离学校很远。 Wǒ jiā lí xuéxiào hěn yuǎn. — Мой дом далеко от школы.'),
                                                                                 (180, '得', 'служебная частица', 'de', 'Частица оценки или результата (ставится между глаголом и характеристикой).', '他说得很好。 Tā shuō de hěn hǎo. — Он говорит очень хорошо.'),
                                                                                 (181, '着', 'суффикс длительного действия', 'zhe', 'Дверь на замке, овечка пасет длительное время — показатель длящегося процесса.', '他笑着说。 Tā xiào zhe shuō. — Он сказал с улыбкой.'),
                                                                                 (182, '过', 'проходить, переходить; суффикс опыта', 'guò', 'Идти (辶) и пересекать границу — преодолевать пространство или получать жизненный опыт.', '我去过北京。 Wǒ qù guò Běijīng. — Я бывал в Пекине.'),
                                                                                 (183, '吧', 'модальная частица (предложение, неуверенность)', 'ba', 'Рот (口) и знакзвука — мягкое приглашение к действию или предположение на конце фразы.', '我们走吧！ Wǒmen zǒu ba! — Пойдемте!'),
                                                                                 (184, '机场', 'аэропорт', 'jīchǎng', 'Самолет/летать (机) + площадка/поле (场); поле для взлета и посадки летательных аппаратов.', '我去机场接朋友。 Wǒ qù jīchǎng jiē péngyou. — Я еду в аэропорт встречать друга.'),
                                                                                 (185, '教室', 'класс, аудитория', 'jiàoshì', 'Учить/обучать (教) + комната/помещение (室); комната для занятий.', '他们在教室里学习。 Tāmen zài jiàoshì lǐ xuéxí. — Они учатся в классе.'),
                                                                                 (186, '房间', 'комната, помещение', 'fángjiān', 'Дом/постройка (房) + пространство/промежуток (间); отдельная комната под крышей.', '这个房间很大。 Zhège fángjiān hěn dà. — Эта комната очень большая.'),
                                                                                 (187, '路', 'дорога, путь', 'lù', 'Нога/идти (足) + каждый/все (各) — дорога, по которой каждый день идут люди.', '这条路很长。 Zhè tiáo lù hěn cháng. — Эта дорога очень длинная.'),
                                                                                 (188, '左边', 'левая сторона, слева', 'zuǒbiān', 'Инструмент/работа (工) + сторона/пространство (边); левая рука трудится.', '书在左边。 Shū zài zuǒbiān. — Книга слева.'),
                                                                                 (189, '右边', 'правая сторона, справа', 'yòubiān', 'Рот (口) под рукой (右手) — правосторонняя зона.', '银行在右边. Yínháng zài yòubiān. — Банк справа.'),
                                                                                 (190, '外', 'снаружи, вне', 'wài', 'Вечер/луна (夕) и гадание/разметка — то, что находится за пределами дома.', '外面 in rain -> 外面下雨了。 Wàimiàn xiàyǔ le. — На улице идет дождь.'),
                                                                                 (191, '旁边', 'рядом, около, сбоку', 'pángbiān', 'Сторона/возле (旁) + пространство (边); соседняя зона.', '他在我旁边。 Tā zài wǒ pángbiān. — Он рядом со мной.'),
                                                                                 (192, '一下', 'немного, разок (о действии)', 'yīxià', 'Один (一) + вниз (下) — одно быстрое движение или короткое действие.', '等一下！ Děng yīxià! — Подожди секунду!'),
                                                                                 (193, '早上', 'утро', 'zǎoshàng', 'Раннее солнце (早) + верх/начало (上); восход солнца на небосводе.', '早上好！ Zǎoshǎo hǎo! — Доброе утро!'),
                                                                                 (194, '晚上', 'вечер, ночь', 'wǎnshàng', 'Солнце заходит, наступает ночь (晚) + время (上).', '晚上我去看电影。 Wǎnshàng wǒ qù kàn diànyǐng. — Вечером я иду в кино.'),
                                                                                 (195, '小时', 'час (промежуток времени)', 'xiǎoshí', 'Маленький (小) + время/период (时); отрезок времени.', '我等了一个小时。 Wǒ děng le yī gè xiǎoshí. — Я прождал один час.'),
                                                                                 (196, '时间', 'время', 'shíjiān', 'Солнце/период (时) + промежуток между стенами (间); рамки времени.', '我没有时间。 Wǒ méiyǒu shíjiān. — У меня нет времени.'),
                                                                                 (197, '去年', 'прошлый год', 'qùnián', 'Уходить (去) + год (年); год, который уже ушел вдаль.', '我去年去了中国。 Wǒ qùnián qù le Zhōngguó. — В прошлом году я ездил в Китай.'),
                                                                                 (198, '日', 'день, солнце, дата', 'rì', 'Пиктограмма солнечного диска с точкой посередине.', '今天是1日。 Jīntiān shì yī hào (rì). — Сегодня 1-е число.'),
                                                                                 (199, '生日', 'день рождения', 'shēngrì', 'Рождаться (生) + день/солнце (日); день появления на свет.', '祝你生日快乐！ Zhù nǐ shēngrì kuàilè! — С днем рождения!'),
                                                                                 (200, '哥哥', 'старший брат', 'gēge', 'Звуковой повтор и символ человека — главный покровитель из братьев.', '我有一个哥哥。 Wǒ yǒu yī gè gēge. — У меня есть старший брат.'),
                                                                                 (201, '姐姐', 'старшая сестра', 'jiějie', 'Женщина (女) с авторитетом в роду, старшая родственница.', '我 姐姐 是 老师。 Wǒ jiějie shì lǎoshī. — Моя старшая сестра — учительница.'),
                                                                                 (203, '妹妹', 'младшая сестра', 'mèimei', 'Женщина (女) + младший росток — самая младшая девочка в семье.', '我的 妹妹 五 岁。 Wǒ de mèimei wǔ suì. — Моей младшей сестре пять лет.'),
                                                                                 (204, '丈夫', 'муж', 'zhàngfu', 'Мужчина ростом в десять ладоней (丈 + 夫) — глава семьи.', '这是我的丈夫。 Zhè shì wǒ de zhàngfu. — Это мой муж.'),
                                                                                 (205, '妻子', 'жена', 'qīzi', 'Женщина (妻) + суффикс (子); спутница жизни под общей крышей.', '他的妻子很漂亮。 Tā de qīzi hěn piàoliang. — Его жена очень красивая.'),
                                                                                 (206, '孩子', 'ребенок, дети', 'háizi', 'Малыш с раскинутыми ручками (孩) + суффикс (子); чадо.', '屋子里有很多孩子。 Wūzi li yǒu hěnduō háizi. — В комнате много детей.'),
                                                                                 (207, '男人', 'мужчина', 'nánrén', 'Пахота/мужская сила на поле (男) + человек (人).', '那个男人是谁？ Nà gè nánrén shì shéi? — Кто тот мужчина?'),
                                                                                 (208, '女人', 'женщина', 'nǚrén', 'Женщина (女) + человек (人); прекрасная половина человечества.', '这个女人很 聪明。 Zhège nǚrén hěn cōngmíng. — Эта женщина очень умная.'),
                                                                                 (209, '服务员', 'официант, обслуживающий персонал', 'fúwùyuán', 'Служить/помогать (服) + дело (务) + человек (员); тот, кто обслуживает.', '服务员，买单！ Fúwùyuán, mǎidān! — Официант, счет!'),
                                                                                 (210, '鱼', 'рыба', 'yú', 'Пиктограмма рыбы: голова, чешуйчатое тело и хвост снизу (灬).', '猫喜欢吃鱼。 Māo xǐhuān chī yú. — Кошка любит есть рыбу.'),
                                                                                 (211, '羊肉', 'баранина', 'yángròu', 'Баран/овца (羊) + мясо (肉); питательное мясо барашка.', '我喜欢吃羊肉。 Wǒ xǐhuān chī yángròu. — Я люблю есть баранину.'),
                                                                                 (212, '牛奶', 'молоко', 'niúnǎi', 'Корова (牛) + молоко/грудь (奶); коровье молоко.', '早上我喝牛奶。 Zǎoshang wǒ hē niúnǎi. — Утром я пью молоко.'),
                                                                                 (213, '鸡蛋', 'яйцо', 'jīdàn', 'Курица (鸡) + яйцо (蛋); птичье яйцо.', '他吃了两个鸡蛋。 Tā chī le liǎng gè jīdàn. — Он съел два яйца.'),
                                                                                 (214, '西瓜', 'арбуз', 'xīguā', 'Запад (西) + дыня/тыква (瓜); заморская сладкая ягода.', '夏天吃西瓜很解暑。 Xiàtiān chī xīguā hěn jiěshǔ. — Летом есть арбуз — отличное спасение от жары.'),
                                                                                 (215, '咖啡', 'кофе', 'kāfēi', 'Два символа с «травяными» ключами (咖啡) — заимствованное звуковое слово для бодрящего напитка.', '我每天喝一杯咖啡。 Wǒ měitiān hē yībēi kāfēi. — Я пью чашку кофе каждый день.'),
                                                                                 (216, '雪', 'снег', 'xuě', 'Дождь (雨) сверху и заметающие хлопья — зимние осадки.', '外面下雪了。 Wàimiàn xià xuě le. — На улице пошел снег.'),
                                                                                 (217, '药', 'лекарство', 'yào', 'Трава (艹) + музыка/радость — целительное зелье, приносящее облегчение.', '生病了要吃药。 Shēngbìng le yào chī yào. — Заболел — нужно пить лекарство.'),
                                                                                 (218, '手机', 'мобильный телефон', 'shǒujī', 'Рука (手) + аппарат/машина (机); аппарат, который всегда в руке.', '我的手机坏了。 Wǒ de shǒujī huài le. — Мой телефон сломался.'),
                                                                                 (219, '手表', 'наручные часы', 'shǒubiǎo', 'Рука (手) + поверхность/циферблат (表); часы на запястье.', '这块手表很贵。 Zhè kuài shǒubiǎo hěn guì. — Эти часы очень дорогие.'),
                                                                                 (220, '眼睛', 'глаз, глаза', 'yǎnjing', 'Глаз (眼) + суффикс (jing); органы зрения, смотрящие на мир.', '她的眼睛很大。 Tā de yǎnjing hěn dà. — У нее большие глаза.'),
                                                                                 (221, '身体', 'тело, здоровье', 'shēntǐ', 'Тело/туловище (身) + туловище/основа (体); физическая оболочка.', '多 运动 对 身体 好。 Duō yùndòng duì shēntǐ hǎo. — Больше спорта полезно для здоровья.'),
                                                                                 (222, '公共汽车', 'автобус', 'gōnggòng qìchē', 'Общий (公共) + паровая машина/автомобиль (汽车); общественный транспорт.', '我坐公共汽车去学校。 Wǒ zuò gōnggòng qìchē qù xuéxiào. — Я еду в школу на автобусе.'),
                                                                                 (223, '报纸', 'газета', 'bàozhǐ', 'Сообщать/объявлять (报) + бумага (纸); новостные бумажные листы.', '爷爷喜欢看报纸。 Yéye xǐhuān kàn bàozhǐ. — Дедушка любит читать газету.'),
                                                                                 (224, '门', 'дверь, ворота', 'mén', 'Пиктограмма двух створок открытой двери со щеколдой.', '请把门打开。 Qǐng bǎ mén dǎkāi. — Пожалуйста, открой дверь.'),
                                                                                 (225, '题', 'тема, вопрос, задание', 'tí', 'Голова/макушка (页) сверху и знак снизу — задача для размышления.', '这道题很难。 Zhè dào tí hěn nán. — Эта задача очень сложная.'),
                                                                                 (226, '课', 'урок, занятие', 'kè', 'Речь (讠) + плод/дерево — учебный предмет или занятие.', '我们开始上课。 Wǒmen kāishǐ shàng kè. — Мы начинаем урок.'),
                                                                                 (227, '姓', 'фамилия, носить фамилию', 'xìng', 'Женщина (女) + рождаться/жизнь (生) — родовая фамилия по материнской линии в древности.', '你贵姓？ Nǐ guì xìng? — Какая у вас фамилия? (уваж.)'),
                                                                                 (228, '问题', 'вопрос, проблема', 'wèntí', 'Спрашивать/навещать (问) + тема/задача (题); то, что требует ответа.', '我有一个问题。 Wǒ yǒu yī gè wèntí. — У меня есть вопрос.'),
                                                                                 (229, '事情', 'дело, событие', 'shìqing', 'Служба/дело (事) + легкий суффикс — житейские дела и заботы.', '我有事情要处理。 Wǒ yǒu shìqing yào chǔlǐ. — У меня есть дела, которые нужно решить.'),
                                                                                 (230, '考试', 'экзамен, тестировать', 'kǎoshì', 'Проверять/испытывать (考) + испытывать/проверять (试); проверка знаний.', '明天 有 考试。 Míngtiān yǒu kǎoshì. — Завтра экзамен.'),
                                                                                 (231, '票', 'билет', 'piào', 'Красивый/проявляющийся знак на бумажном пропуске.', '一张去北京的票。 Yī zhāng qù Běijīng de piào. — Один билет до Пекина.'),
                                                                                 (232, '意思', 'значение, смысл, интерес', 'yìsi', 'Мысль/сердце (意) + мыслить/мысль (思); игра ума и подтекст.', '这个词是什么意思？ Zhège cí shì shénme yìsi. — Что означает это слово?'),
                                                                                 (233, '颜色', 'цвет', 'yánsè', 'Лицо/выражение (颜) + цвет/краска (色); палитра красок.', '天空的颜色很蓝。 Tiānkōng de yánsè hěn lán. — Цвет неба очень синий.'),
                                                                                 (234, '铅笔', 'карандаш', 'qiānbǐ', 'Свинец/металл (铅) + кисть (笔); грифельный карандаш для письма.', '用铅笔写字。 Yòng qiānbǐ xiě zì. — Писать карандашом.'),
                                                                                 (235, '面条', 'лапша', 'miàntiáoniǎo', 'Мука/плоскость (面) + полоски/нити (条); длинная тянутая лапша.', '中午我想吃面条。 Zhōngwǔ wǒ xiǎng chī miàntiáo. — В обед я хочу съесть лапшу.'),
                                                                                 (236, '火车站', 'железнодорожный вокзал', 'huǒchēzhàn', 'Поезд (火车) + станция/остановка (站); место остановки поездов.', '我在火车站等你。 Wǒ zài huǒchēzhàn děng nǐ. — Я жду тебя на вокзале.'),
                                                                                 (237, '公司', 'компания, фирма', 'gōngsī', 'Общий/общественный (公) + управлять/служба (司); коммерческая организация.', '他在一家公司工作。 Tā zài yī jiā gōngsī gōngzuò. — Он работает в компании.'),
                                                                                 (238, '宾馆', 'гостиница, отель', 'bīngguǎn', 'Гость (宾) + большой дом/здание (馆); дом для приема гостей.', '这家宾馆很干净。 Zhè jiā bīngguǎn hěn gānjìng. — Этот отель очень чистый.'),
                                                                                 (239, '说话', 'говорить, разговаривать', 'shuōhuà', 'Говорить (说) + слова/речь (话); произносить вслух.', '请不要说话。 Qǐng búyào shuōhuà. — Пожалуйста, не разговаривайте.'),
                                                                                 (240, '卖', 'продавать', 'mài', 'Товар + крышка/выставление на прилавок — продажа за деньги.', '她在卖水果。 Tā zài mài shuǐguǒ. — Она продает фрукты.'),
                                                                                 (241, '问', 'спрашивать', 'wèn', 'Рот (口) выглядит из-за ворот — гость за затвором задает вопрос стражникам.', '我有问题问你。 Wǒ yǒu wèntí wèn nǐ. — У меня есть вопрос к тебе.'),
                                                                                 (242, '走', 'идти, ходить', 'zǒu', 'Пиктограмма человека, шагающего вперед на длинных ногах.', '我们走吧！ Wǒmen zǒu ba! — Пойдемте!'),
                                                                                 (243, '进', 'входить, въезжать', 'jìn', 'Птица/шаг движется вперед (井), пересекая черту внутрь помещения.', '请进！ Qǐng jìn! — Войдите, пожалуйста!'),
                                                                                 (244, '出', 'выходить, появляться', 'chū', 'Росток или предмет пробивается наружу из укрытия сквозь щель.', '他出去了。 Tā chū qù le. — Он вышел.'),
                                                                                 (245, '跑步', 'бегать, бег', 'pǎobù', 'Бежать (跑) + шаг/ходьба (步); активный бег трусцой.', '我每天早上跑步。 Wǒ měitiān zǎoshang pǎobù. — Я каждое утро бегаю.'),
                                                                                 (246, '到', 'прибывать, доходить', 'dào', 'Стрела достигает цели + знак прибытия (到 destination).', '我到家了。 Wǒ dào jiā le. — Я дома (добрался до дома).'),
                                                                                 (247, '穿', 'надевать, носить (одежду)', 'chuān', 'Дерево/отверстие (牙) под крышей — просовывать руки и тело в одежду.', '穿新衣服。 Chuān xīn yīfu. — Надевать новую одежду.'),
                                                                                 (248, '洗', 'мыть, стирать', 'xǐ', 'Вода (氵) и процесс очищения руками.', '洗 衣服 -> 洗手。 Xǐ shǒu. — Мыть руки.'),
                                                                                 (249, '给', 'давать, для, к', 'gěi', 'Нить/шелк (纟) + передавать — протягивать что-то другому человеку.', '这本书给你。 Zhè běn shū gěi nǐ. — Эта книга тебе.'),
                                                                                 (250, '找', 'искать, находить', 'zhǎo', 'Рука (扌) и знак поиска — шарить руками в поисках пропажи.', '你在找什么？ Nǐ zài zhǎo shénme? — Что ты ищешь?'),
                                                                                 (251, '懂', 'понимать', 'dǒng', 'Сердце/ум (忄) и сложная структура — дойти умом до сути.', '我听懂了。 Wǒ tīng dǒng le. — Я расслышал и понял.'),
                                                                                 (252, '笑', 'смеяться, улыбаться', 'xiào', 'Брови и прищуренные глаза под шляпой — лицо человека в улыбке.', '他笑了。 Tā xiào le. — Он улыбнулся.'),
                                                                                 (253, '告诉', 'рассказывать, сообщать', 'gàosù', 'Корова под крышей (告) + рассказывать/вести (诉); передача информации.', '请告诉我。 Qǐng gàosù wǒ. — Пожалуйста, скажи мне.'),
                                                                                 (254, '准备', 'подготавливать, готовить', 'zhǔnbèiprepare', 'Точный/владеть (准) + готовить/снаряжение (备); полная готовность.', '我准备好了。 Wǒ zhǔnbèi hǎo le. — Я готов.'),
                                                                                 (255, '开始', 'начинать, начало', 'kāishǐ', 'Открывать/пускать (开) + начинать/основа (始); старт процесса.', '我们开始上课。 Wǒmen kāishǐ shàng kè. — Мы начинаем урок.'),
                                                                                 (256, '介绍', 'знакомить, представлять', 'jièshào', 'Посредник/соединять (介) + представление/продолжение (绍); мостик между людьми.', '我来介绍一下。 Wǒ lái jièshào yīxià. — Я представлю (познакомлю).'),
                                                                                 (257, '帮助', 'помогать, помощь', 'bāngzhù', 'Помогать/стена (帮) + помогать/поддержка (助); плечо друга в трудную минуту.', '谢谢你的帮助。 Xièxie nǐ de bāngzhù. — Спасибо за твою помощь.'),
                                                                                 (258, '玩', 'играть, развлекаться', 'wán', 'Король/нефрит (王) в руке — играть с ценными игрушками.', '孩子们在玩。 Háizimen zài wán. — Дети играют.'),
                                                                                 (259, '送', 'дарить, провожать', 'sòng', 'Идти (辶) + дарить/преподносить — вручать подарок или провожать в путь.', '送你一个礼物。 Sòng nǐ yī gè lǐwù. — Дарую тебе подарок.'),
                                                                                 (260, '等', 'ждать, ожидать', 'děng', 'Бамбуковые планки (竹) ровно в ряд — терпеливо стоять в очереди и ждать.', '等我一会儿。 Děng wǒ yīhuìr. — Подожди меня немного.'),
                                                                                 (261, '让', 'велеть, разрешать, позволять', 'ràng', 'Речь (讠) + мягкий знак — отдавать распоряжение или уступать дорогу.', '让一下。 Ràng yīxià. — Уступите дорогу / Пропустите.'),
                                                                                 (262, '起床', 'вставать с постели', 'qǐchuáng', 'Подниматься (起) + кровать/постель (床); просыпаться и вставать.', '我七点起床。 Wǒ qī diǎn qǐchuáng. — Я встаю в семь часов.'),
                                                                                 (263, '唱歌', 'петь песню', 'chànggē', 'Петь/звук ртом (唱) + песня/мелодия (歌); исполнять вокальный номер.', '她喜欢唱歌。 Tā xǐhuān chànggē. — Она любит петь.'),
                                                                                 (264, '跳舞', 'танцевать', 'tiàowǔ', 'Прыгать (跳) + танец/движения (舞); ритмичные прыжки и движения тела.', '他们会跳舞。 Tāmen huì tiàowǔ. — Они умеют танцевать.'),
                                                                                 (265, '旅游', 'путешествовать', 'lǚyóu', 'Странствовать/отряд (旅) + плавать/гулять (游); поездка в новые места.', '我喜欢旅游。 Wǒ xǐhuān lǚyóu. — Я люблю путешествовать.'),
                                                                                 (266, '上班', 'выходить на работу, дежурить', 'shàngbān', 'Верх/на (上) + рабочая смена/офис (班); отправляться на рабочее место.', '我八点上班。 Wǒ bā diǎn shàngbān. — Я выхожу на работу в восемь часов.'),
                                                                                 (267, '生病', 'заболеть', 'shēngbìng', 'Рождаться/появляться (生) + болезнь/недуг (病); подхватить хворь.', '他生病了，没去上学。 Tā shēngbìng le, méi qù shàngxué. — Он заболел и не пошел в школу.'),
                                                                                 (268, '休息', 'отдыхать', 'xiūxi', 'Человек (亻) у дерева (木) — сидеть в тени и набираться сил.', '累了就休息一会儿。 Lèi le jiù xiūxi yīhuìr. — Устал — отдохни немного.'),
                                                                                 (269, '运动', 'заниматься спортом, движение', 'yùndòng', 'Движение/перемещение (运) + движение/активность (动); физическая разминка.', '我每天运动半小时。 Wǒ měitiān yùndòng bàn xiǎoshí. — Я занимаюсь спортом полчаса каждый день.'),
                                                                                 (270, '游泳', 'плавать', 'yóuyǒng', 'Плавать/вода (游) + плавать (泳); водные заплывы.', '夏天我喜欢游泳。 Xiàtiān wǒ xǐhuān yóuyǒng. — Летом я люблю плавать.'),
                                                                                 (271, '踢足球', 'играть в футбол', 'tī zúqiú', 'Пинать ногой (踢) + нога (足) + мяч (球); классическая командная игра с мячом.', '我周末踢足球。 Wǒ zhōumò tī zúqiú. — Я играю в футбол по выходным.'),
                                                                                 (272, '打篮球', 'играть в баскетбол', 'dǎ lánqiú', 'Бить/играть руками (打) + корзина (篮) + мяч (球); забрасывание мяча в кольцо.', '哥哥喜欢打篮球。 Gēge xǐhuān dǎ lánqiú. — Старший брат любит играть в баскетбол.'),
                                                                                 (273, '完', 'кончать, завершать', 'wán', 'Крыша и полный порядок — дело сделано, процесс завершен.', '作业做完了。 Zuòyè zuò wán le. — Домашняя работа сделана (завершена).'),
                                                                                 (274, '觉得', 'считать, полагать, чувствовать', 'juédé', 'Ощущать/воспринимать (觉) + приобретать понимание (得); личное мнение или ощущение.', '我觉得这个很好。 Wǒ juédé zhège hěn hǎo. — Я считаю, что это очень хорошо.'),
                                                                                 (275, '知道', 'знать, иметь представление', 'zhīdao', 'Знать/ведать (知) + путь/дорога (道); владеть информацией и ориентироваться в вопросе.', '我知道这件事。 Wǒ zhīdao zhè jiàn shì. — Я знаю об этом деле.'),
                                                                                 (276, '希望', 'надеяться, надежда', 'xīwàng', 'Редкий/стремиться (希) + смотреть вдаль/ожидать (望); устремленный в будущее взгляд.', '我希望去中国。 Wǒ xīwàng qù Zhōngguó. — Я надеюсь поехать в Китай.'),
                                                                                 (277, '可以', 'могу, можно, разрешается', 'kěyǐ', 'Подходящий/достойный (可) + быть способным/управлять (以); наличие разрешения или возможности.', '我可以进来吗？ Wǒ kěyǐ jìnlái ma? — Можно мне войти?'),
                                                                                 (278, '要', 'хотеть, нужно, собираться', 'yào', 'Женщина и руки — то, чего хочется схватить или в чем есть острая необходимость.', '我要一杯水。 Wǒ yào yībēi shuǐ. — Я хочу чашку воды.'),
                                                                                 (279, '可能', 'возможно, мочь', 'kěnéng', 'Разрешено/можно (可) + сила/способность (能); вероятность наступления события.', '明天可能下雨。 Míngtiān kěnéng xiàyǔ. — Завтра возможно пойдет дождь.'),
                                                                                 (280, '高', 'высокий', 'gāo', 'Пиктограмма многоярусной высокой башни или замка с крышей.', '这座山很高。 Zhè zuò shān hěn gāo. — Эта гора очень высокая.'),
                                                                                 (281, '红', 'красный', 'hóng', 'Нить/шелк (纟) + красный/рабочий свет — цвет пламени и праздника.', '他穿红衣服。 Tā chuān hóng yīfu. — Он носит красную одежду.'),
                                                                                 (282, '白', 'белый', 'bái', 'Лучи солнца пробиваются сквозь заросли — чистый белый цвет.', '白云在天上。 Bái yún zài tiānshàng. — Белые тучи на небе.'),
                                                                                 (283, '黑', 'черный', 'hēi', 'Дым над очагом или сажа, покрывающая кострище — угольно-черный цвет.', '黑猫很 漂亮。 Hēi māo hěn piàoliang. — Черная кошка очень красивая.'),
                                                                                 (284, '忙', 'занятый', 'máng', 'Сердце (忄) теряет покой из-за обилия дел (亡 — теряться).', '你最近忙吗？ Nǐ zuìjìn máng ma? — Ты в последнее время занят?'),
                                                                                 (285, '快', 'быстрый, скорый', 'kuài', 'Сердце (忄) и скорость движения — быстрый темп, радость.', '时间过得真快！ Shíjiān guò de zhēn kuài! — Время летит действительно быстро!'),
                                                                                 (286, '慢', 'медленный', 'màn', 'Сердце (忄) бьется спокойно и размеренно — отсутствие спешки.', '请开慢一点。 Qǐng kāi màn yīdiǎn. — Пожалуйста, ведите немного медленнее.'),
                                                                                 (287, '远', 'далекий, далеко', 'yuǎn', 'Идти (辶) вдаль к черте горизонта — большая дистанция.', '我家离得很远。 Wǒ jiā lí de hěn yuǎn. — Мой дом находится очень далеко.'),
                                                                                 (288, '近', 'близкий, близко', 'jìn', 'Идти (辶) к цели, которая уже совсем рядом на расстоянии вытянутой руки.', '学校离这儿很近。 Xuéxiào lí zhèr hěn jìn. — Школа совсем близко отсюда.'),
                                                                                 (289, '好吃', 'вкусный', 'hǎochī', 'Хороший/легкий (好) + есть/кушать (吃); то, что приятно съесть.', '中国菜很好吃。 Zhōngguó cài hěn hǎochī. — Китайская еда очень вкусная.'),
                                                                                 (290, '累', 'уставший, утомленный', 'lèi', 'Поле (田) и нити — тяжелый физический труд до утомления.', '今天工作很累。 Jīntiān gōngzuò hěn lèi. — Сегодня на работе было очень устало.'),
                                                                                 (291, '长', 'длинный', 'cháng', 'Пышные волосы старца или протянутая вдаль линия.', '这条河很长。 Zhè tiáo hé hěn cháng. — Эта река очень длинная.'),
                                                                                 (292, '新', 'новый', 'xīn', 'Топор (斤) рубит дерево (木) — свежий срез свежесрубленного дерева.', '我买了一辆新车。 Wǒ mǎi le yí liàng xīn chē. — Я купил новую машину.'),
                                                                                 (293, '贵', 'дорогой (о цене)', 'guì', 'Раковина каури (деньги) и подземный ключи — ценная вещь, за которую просят много.', '这个手机太贵了。 Zhège shǒujī tài guì le. — Этот телефон слишком дорогой.'),
                                                                                 (294, '便宜', 'дешевый', 'piányi', 'Удобный, выгодный — то, что доступно по цене без лишних затрат.', '这件衣服很便宜。 Zhè jiàn yīfu hěn piányi. — Эта одежда очень дешевая.'),
                                                                                 (295, '晴', 'ясный (о погоде)', 'qíng', 'Солнце (日) + чистый/синий цвет (青) — ясное небо без туч.', '今天天气 晴。 Jīntiān tiānqì qíng. — Сегодня ясная погода.'),
                                                                                 (296, '阴', 'пасмурный, инь', 'yīn', 'Холм/склон и облака — теневая сторона, тучи на небе.', '今天阴天。 Jīntiān yīntiān. — Сегодня пасмурный день.'),
                                                                                 (297, '错', 'ошибочный, неправильный', 'cuò', 'Металл/золото и погрешность — изъян, отклонение от нормы.', '我 认 错 人 了。 Wǒ rèn cuò rén le. — Я обознался (принял не за того человека).'),
                                                                                 (298, '快乐', 'счастливый, радостный', 'kuàilè', 'Быстрый/веселый (快) + музыка/радость (乐); состояние душевного подъема.', '祝你生日快乐！ Zhù nǐ shēngrì kuàilè! — С днем рождения! (Счастливого дня рождения!)'),
                                                                                 (299, '对', 'верный, правильный; к, по отношению к', 'duì', 'Правая рука и знак соответствия — совпадение, попадание в точку.', '你的回答很对。 Nǐ de huídá hěn duì. — Твой ответ абсолютно верен.'),
                                                                                 (300, '游戏', 'игра', 'yóuxì', 'Плавать/гулять (游) + играть/развлекаться (戏); видеоигры или развлечения.', '弟弟喜欢玩游戏。 Dìdi xǐhuān wán yóuxì. — Младший брат любит играть в игры.'),
                                                                                 (301, '复习', 'повторять (урок)', 'fùxí', 'Возвращаться/снова (复) + упражняться/учиться (习); повторение пройденного.', '考试前要复习。 Kǎoshì qián yào fùxí. — Перед экзаменом нужно повторить материал.'),
                                                                                 (302, '面包', 'хлеб', 'miànbāo', 'Мука/плоскость (面) + сверток/сумка (包); завернутая в оболочку булка хлеба.', '早餐我吃面包。 Zǎocān wǒ chī miànbāo. — На завтрак я ем хлеб.'),
                                                                                 (303, '周末', 'выходные', 'zhōumò', 'Круг/неделя (周) + конец/край (末); завершение рабочей недели.', '周末你有什么 打算？ Zhōumò nǐ yǒu shénme dǎsuan? — Какие у тебя планы на выходные?'),
                                                                                 (304, '搬', 'двигать, переезжать', 'bān', 'Рука (扌) переносит тяжелые предметы (舟) с места на место.', '我们下个月搬家。 Wǒmen xià gè yuè bānjiā. — Мы в следующем месяце переезжаем.'),
                                                                                 (305, '跟', 'с, вместе с; и', 'gēn', 'Нога/пята (足) следует шаг в шаг за кем-то.', '我和朋友一起去。 Wǒ gēn péngyou yìqǐ qù. — Я иду вместе с другом.'),
                                                                                 (306, '地图', 'карта', 'dìtú', 'Земля (地) + чертеж/план (图); схема земной поверхности.', '请 给我 一张地图。 Qǐng gěi wǒ yī zhāng dìtú. — Дайте мне, пожалуйста, карту.'),
                                                                                 (307, '作业', 'домашнее задание', 'zuòyè', 'Делать (作) + дело/отрасль (业); то, что задали сделать на дом.', '我 已经 做 完 作业 了。 Wǒ yǐjīng zuò wán zuòyè le. — Я уже сделал домашнюю работу.'),
                                                                                 (308, '打算', 'планировать, намереваться', 'dǎsuan', 'Вычислять/ударять (打) + подсчет/план (算); предварительный расчет и замысел.', '你 打算 什么时候 去？ Nǐ dǎsuan shénme shíhou qù? — Когда ты планируешь поехать?'),
                                                                                 (309, '带', 'брать с собой, приносить', 'dài', 'Ремень/повязка и руки — то, что закрепляют при себе в дорогу.', '出门别忘带伞。 Chūmén bié wàng dài sǎn. — Выходя из дома, не забудь взять зонт.'),
                                                                                 (310, '南方', 'юг, южная сторона', 'nánfāng', 'Юг (南) + сторона (方); теплое южное направление.', '南方冬天不冷。 Nánfāng dōngtiān bù lěng. — На юге зимой не холодно.'),
                                                                                 (311, '北方', 'север, северные районы', 'běifāng', 'Север/спина (北) + сторона (方); холодные северные земли.', '北方人喜欢吃面食。 Běifāng rén xǐhuān chī miànshí. — Северяне любят мучные изделия.'),
                                                                                 (312, '啊', 'восклицательная частица', 'a', 'Рот (口) + звук удивления или эмоции на конце фразы.', '天气真好啊！ Tiānqì zhēn hǎo a! — Какая же хорошая погода!'),
                                                                                 (313, '着急', 'волноваться, торопиться', 'zháojí', 'Жчь/тревожить (着) + сердце/огонь (急); когда душа горит от переживаний.', '别着急，慢慢来。 Bié zháojí, mànmàn lái. — Не волнуйся, делай не спеша.'),
                                                                                 (314, '一直', 'всегда, непрерывно, прямо', 'yìzhí', 'Один (一) + прямой/ровный (直); движение по прямой без остановок.', '一直往前走。 Yìzhí wǎng qián zǒu. — Идите всё прямо вперед.'),
                                                                                 (315, '腿', 'нога (от бедра до стопы)', 'tuǐ', 'Луна/тело (月) + 退 (отступать) — часть тела для ходьбы.', '走路走得腿疼。 Zǒu lù zǒu de tuǐ téng. — От ходьбы заболели ноги.'),
                                                                                 (316, '疼', 'болеть', 'téng', 'Болезнь/недуг (疒) + зима/холод — пронизывающая боль.', '我的头有点疼。 Wǒ de tóu yǒudiǎn téng. — У меня немного болит голова.'),
                                                                                 (317, '脚', 'стопа, нога', 'jiǎo', 'Мясо/тело (月) + знак завершения — нижняя опора тела.', '穿鞋子要合脚。 Chuān xiézi yào héjiǎo. — Обувь должна быть по ноге.'),
                                                                                 (318, '树', 'дерево', 'shù', 'Дерево (木) + опора/внутренности (对) — мощное растущее растение.', ' 院子 里 有 很 多 树。 Yuànzi li yǒu hěnduō shù. — Во дворе много деревьев.'),
                                                                                 (319, '容易', 'легкий, простой', 'róngyì', 'Луна/изменение (易) — то, что дается легко и меняется без труда.', '这个问题很 容易。 Zhège wèntí hěn róngyì. — Этот вопрос очень простой.'),
                                                                                 (320, '难', 'трудный, сложный', 'nán', 'Птица/сложный элемент сбоку — то, с чем тяжело справиться.', '汉字 writing -> 汉字很难学。 Hànzì hěn nán xué. — Иероглифы учить сложно.'),
                                                                                 (321, '太太', 'госпожа, жена', 'tàitai', 'Большой (大) с дополнительным знаком почтения — замужняя женщина.', '这是 Lee, his wife -> 这是李太太。 Zhè shì Lǐ tàitai. — Это госпожа Ли.'),
                                                                                 (322, '秘书', 'секретарь', 'mìshū', 'Таинственный/секретный (秘) + книга/документ (书); помощник по важным бумагами.', '他是公司的秘书。 Tā shì gōngsī de mìshū. — Он секретарь компании.'),
                                                                                 (323, '经理', 'менеджер, директор', 'jīnglǐ', 'Проходить сквозь (经) + управлять (理); управленец высшего звена.', '王经理不在办公室。 Wáng jīnglǐ bú zài bàngōngshì. — Директор Ван не в кабинете.'),
                                                                                 (324, '办公室', 'офис, рабочий кабинет', 'bàngōngshì', 'Работать (办) + общественное дело (公) + комната (室); рабочее помещение.', '我在办公室工作。 Wǒ zài bàngōngshì gōngzuò. — Я работаю в офисе.'),
                                                                                 (325, '辆', 'счетное слово для транспорта', 'liàng', 'Колесный экипаж или машина.', '我买了一辆新车。 Wǒ mǎi le yí liàng xīn chē. — Я купил новую машину.'),
                                                                                 (326, '楼', 'этаж, многоэтажное здание', 'lóu', 'Дерево (木) + здание/возвышение (娄); многоуровневая постройка.', '他在三楼。 Tā zài sān lóu. — Он на третьем этаже.'),
                                                                                 (327, '拿', 'брать, держать в руках', 'ná', 'Рука (手) объединяет предмет — взять в ладонь.', '请把书拿给我。 Qǐng bǎ shū ná gěi wǒ. — Пожалуйста, возьми и дай мне книгу.'),
                                                                                 (328, '把', 'держать / предлог бǎ', 'bǎ', 'Рука (扌) охватывает рукоятку инструмента.', '把门关上。 Bǎ mén guān shàng. — Закрой дверь (с конструкцией бǎ).'),
                                                                                 (329, '伞', 'зонт', 'sǎn', 'Пиктограмма раскрытого купола с подвесными спицами от дождя.', '下雨了，带伞吧。 Xiàyǔ le, dài sǎn ba. — Пошел дождь, бери зонт.'),
                                                                                 (330, '胖', 'полный, толстый', 'pàng', 'Мясо/тело (月) + изобилие/половина — округлые формы.', '这只猫吃得很胖。 Zhè zhī māo chī de hěn pàng. — Эта кошка отъелась и стала толстой.'),
                                                                                 (331, '其实', 'на самом деле, фактически', 'qíshí', 'Там/тот (其) + реальность/время (实); подлинное положение дел.', '其实我不知道。 Qíshí wǒ bù zhīdao. — На самом деле я не знаю.'),
                                                                                 (332, '瘦', 'худой, тощий', 'shòu', 'Болезнь (疒) + истощение — излишняя стройность или худоба.', '他最近瘦了。 Tā zuìjìn shòu le. — Он в последнее время похудел.'),
                                                                                 (333, '饮料', 'напиток', 'yǐnliào', 'Пиить (饮) + материал/жидкость (料); то, что утоляет жажду.', '你想喝什么饮料？ Nǐ xiǎng hē shénme yǐnliào. — Какой напиток ты хочешь выпить?'),
                                                                                 (334, '花茶', 'цветочный чай', 'huāchá', 'Цветок (花) + чай (茶); ароматный настой из лепестков.', '我喜欢喝花茶。 Wǒ xǐhuān hē huāchá. — Я люблю пить цветочный чай.'),
                                                                                 (335, '绿茶', 'зеленый чай', 'lǜchá', 'Зеленый (绿) + чай (茶); традиционный полезный напиток.', '绿茶对身体好。 Lǜchá duì shēntǐ hǎo. — Зеленый чай полезен для здоровья.'),
                                                                                 (336, '水果', 'фрукт', 'shuǐguǒ', 'Вода/сок (水) + плод/результат (果); сочные дады природы.', '多吃水果对身体好。 Duō chī shuǐguǒ duì shēntǐ hǎo. — Есть больше фруктов полезно.'),
                                                                                 (337, '衬衫', 'рубашка', 'chènshān', 'Исподнее/подкладка (衬) + одежда/платье (衫); рубашка с воротником.', '这件白衬衫很好看。 Zhè jiàn bái chènshān hěn hǎokàn. — Эта белая рубашка очень красивая.'),
                                                                                 (338, '裤子', 'брюки, штаны', 'kùzi', 'Одежда для ног (裤) + суффикс (子).', '这条裤子太长了。 Zhè tiáo kùzi tài cháng le. — Эти брюки слишком длинные.'),
                                                                                 (339, '还是', 'или / всё же', 'háishi', 'Возврат/еще (还) + быть (是); выбор между вариантами в вопросе.', '你喝茶还是咖啡？ Nǐ hē chá háishi kāfēi? — Ты будешь чай или кофе?'),
                                                                                 (340, '爬山', 'подниматься в гору, альпинизм', 'páshān', 'Карабкаться/ползти (爬) + гора (山); пеший подъем на возвышенность.', '周末我们去爬山。 Zhōumò wǒmen qù páshān. — На выходных мы идем в горы.'),
                                                                                 (341, '小心', 'осторожный, быть аккуратным', 'xiǎoshīn', 'Маленький/аккуратный (小) + сердце (心); беречь себя, действовать с умом.', '路上小心！ Lùshang xiǎoxīn! — Будь осторожен по дороге!'),
                                                                                 (342, '条', 'счетное слово (для длинных предметов)', 'tiáo', 'Длинная ветка или полоска ткани.', '一条河 / 一条裤子。 Yī tiáo hé / yī tiáo kùzi. — Одна река / одни брюки.'),
                                                                                 (343, '记得', 'помнить, запоминать', 'jìde', 'Запоминать/хранить в памяти (记) + приобретать/обладать (得).', '你还记得我吗？ Nǐ hái jìde wǒ ma? — Ты меня еще помнишь?'),
                                                                                 (344, '元', 'юань (денежная единица)', 'yuán', 'Голова сверху + основание — базовая денежная единица.', '这本书二十元。 Zhè běn shū èrshí yuán. — Эта книга стоит двадцать юаней.'),
                                                                                 (345, '新鲜', 'свежий', 'xīnxiān', 'Новый (新) + свежий/редкий (鲜) — только что с грядки или из магазина.', '这些水果很新鲜. Zhèxiē shuǐguǒ hěn xīnxiān. — Эти фрукты очень свежие.'),
                                                                                 (346, '甜', 'сладкий', 'tián', 'Язык (舌) пробует сладость капли во рту (甘).', '这个西瓜很甜。 Zhè jiàn xīguā hěn tián. — Этот арбуз очень сладкий.'),
                                                                                 (347, '只', 'только / счетное слово для птиц/животных', 'zhǐ', 'Одиночный элемент (только одна штука).', '我只有一本书。 Wǒ zhǐ yǒu yī běn shū. — У меня есть только одна книга.'),
                                                                                 (348, '放', 'класть, ставить', 'fàng', 'Направление/отпускать (方) + рука — разместить предмет на полку.', '把书放在桌子上。 Bǎ shū fàng zài zhuōzi shàng. — Положи книгу на стол.'),
                                                                                 (349, '或者', 'или (в утверждениях)', 'huòzhě', 'Возможность/выбор вариантов в утвердительном предложении.', '我们可以 V или V -> 我们可以 走路 或者 坐车。 Wǒmen kěyǐ zǒu lù huòzhě zuò chē. — Мы можем пойти пешком или поехать на машине.'),
                                                                                 (350, '舒服', 'комфортный, удобный', 'shūfu', 'Растягиваться/расслабляться (舒) + успокаивать/уют (服); телесный и душевный комфорт.', '今天天气真舒服。 Jīntiān tiānqì zhēn shūfu. — Сегодня погода действительно комфортная.');
